-- =====================================================================
-- HOREB: Grade 3 Environmental Activities skills, prerequisites and misconceptions (owner, 19 Nov 2026)
-- =====================================================================
-- NOT RUN. Run in Supabase Dashboard -> SQL Editor, after 20261110_curriculum.sql (the five curriculum tables); the Environmental Activities grades in order, 1 to 3 (prerequisites name the grade below; there is no foreign key on them). Idempotent: safe to run twice.
-- WHY: Environmental Activities Grade 3 had KICD outcomes only (curriculum/environmental_activities/g3.json); on 19 Nov 2026 it was mapped to the Grade 5 Maths standard (a skill for every testable outcome, practical outcomes to the teacher's KICD rubric, two or more prerequisites and four misconceptions per skill, a teaching pack). This loads 15 skills (proposed), 34 prerequisites (proposed) and 60 misconceptions (draft)
-- for 12 of 12 sub-strands, for the teacher reviewer. Outcomes are KICD's own words and are not changed.
-- GENERATED by scripts/build-environmental-grade.mjs 3 from curriculum/environmental_activities/g3.json. Do not edit by hand.
-- The sub-strands and outcomes are inserted first (do nothing if present) so the foreign keys hold.
-- =====================================================================
BEGIN;
DELETE FROM public.curriculum_prerequisites WHERE skill_code LIKE 'ENVI.G3.%' AND requires_kind = 'outcome' AND status = 'proposed' AND (skill_code || '|' || requires_code) <> ALL (ARRAY['ENVI.G3.SOCIAL.OUR_LIVING_ENVIRONMENT.BEDDING|ENVI.G2.SOCIAL.OUR_HOME.a', 'ENVI.G3.SOCIAL.OUR_LIVING_ENVIRONMENT.BEDDING|ENVI.G2.SOCIAL.OUR_HOME.b', 'ENVI.G3.SOCIAL.OUR_LIVING_ENVIRONMENT.BEDDING|ENVI.G1.SOCIAL.OUR_HOME.a', 'ENVI.G3.SOCIAL.FAMILY_NEEDS_EMOTIONAL_N.FEELINGS|ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS.a', 'ENVI.G3.SOCIAL.FAMILY_NEEDS_EMOTIONAL_N.FEELINGS|ENVI.G1.SOCIAL.FAMILY_NEEDS.a', 'ENVI.G3.SOCIAL.FAMILY_NEEDS_EMOTIONAL_N.EMOTIONAL_NEEDS|ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS.c', 'ENVI.G3.SOCIAL.FOOD_IN_OUR_ENVIRONMENT.FOOD_GROUPS|ENVI.G2.RESOUR.ANIMALS.a', 'ENVI.G3.SOCIAL.FOOD_IN_OUR_ENVIRONMENT.FOOD_GROUPS|ENVI.G1.SOCIAL.FAMILY_NEEDS.c', 'ENVI.G3.SOCIAL.FOOD_IN_OUR_ENVIRONMENT.FOOD_GROUPS|ENVI.G1.SOCIAL.OUR_MARKET.c', 'ENVI.G3.SOCIAL.OUR_COMMUNITY.SAFE_PLACES|ENVI.G2.SOCIAL.OUR_SCHOOL.b', 'ENVI.G3.SOCIAL.OUR_COMMUNITY.SAFE_PLACES|ENVI.G1.SOCIAL.OUR_SCHOOL.c', 'ENVI.G3.SOCIAL.OUR_COMMUNITY.SAFE_PLACES|ENVI.G1.SOCIAL.OUR_HOME.b', 'ENVI.G3.SOCIAL.OUR_COMMUNITY.ROAD_SIGNS|ENVI.G2.SOCIAL.OUR_MARKET.a', 'ENVI.G3.SOCIAL.OUR_COMMUNITY.ROAD_SIGNS|ENVI.G1.SOCIAL.OUR_SCHOOL.c', 'ENVI.G3.SOCIAL.CULTURAL_EVENTS.CULTURAL_EVENTS|ENVI.G2.SOCIAL.OUR_RIGHTS_AND_RESPONSIB.b', 'ENVI.G3.NATURA.WEATHER.BAD_WEATHER|ENVI.G2.NATURA.WEATHER.a', 'ENVI.G3.NATURA.WEATHER.BAD_WEATHER|ENVI.G2.NATURA.WEATHER.c', 'ENVI.G3.NATURA.SOIL.SOIL_TYPES|ENVI.G2.NATURA.SOIL.b', 'ENVI.G3.NATURA.SOIL.SOIL_TYPES|ENVI.G2.NATURA.SOIL.a', 'ENVI.G3.NATURA.HEAT.HEAT_SOURCES|ENVI.G2.NATURA.LIGHT.a', 'ENVI.G3.NATURA.HEAT.HEAT_SOURCES|ENVI.G1.NATURA.WEATHER_AND_THE_SKY.a', 'ENVI.G3.RESOUR.WATER.CLEAN_WATER|ENVI.G2.RESOUR.WATER.c', 'ENVI.G3.RESOUR.WATER.CLEAN_WATER|ENVI.G2.RESOUR.WATER.a', 'ENVI.G3.RESOUR.PLANTS.PLANT_SAFETY|ENVI.G2.RESOUR.PLANTS.b', 'ENVI.G3.RESOUR.PLANTS.PLANT_SAFETY|ENVI.G1.RESOUR.PLANTS.a', 'ENVI.G3.R