INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G3.SOCIAL.OUR_LIVING_ENVIRONMENT.BEDDING', 'ENVI.G3.SOCIAL.OUR_LIVING_ENVIRONMENT', 'environmental_activities', 3, 'Identify locally available things used as bedding and say how to keep a sleeping area clean', ARRAY['ENVI.G3.SOCIAL.OUR_LIVING_ENVIRONMENT.a']::text[], 'Names locally available bedding (mattress, mat, blanket, bedsheet, pillow, sisal or reed mat, gunny-bag mattress) and says how a sleeping area is kept clean: air and sun the bedding, wash sheets, sweep under the bed, keep food and shoes away, wash and air bedding after bedwetting without shaming. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (ENVI.G3.RUBRIC.1.1), never as a phone question: b) carry out hygiene practises in sleeping areas for a healthy environment.', '["picture choice: which is bedding","what to do to keep bedding clean","odd one out"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G3.SOCIAL.FAMILY_NEEDS_EMOTIONAL_N.FEELINGS', 'ENVI.G3.SOCIAL.FAMILY_NEEDS_EMOTIONAL_N', 'environmental_activities', 3, 'Label emotions in self and others and describe how people express them', ARRAY['ENVI.G3.SOCIAL.FAMILY_NEEDS_EMOTIONAL_N.a', 'ENVI.G3.SOCIAL.FAMILY_NEEDS_EMOTIONAL_N.c']::text[], 'Labels happy, sad, angry, afraid and surprised in faces, body and stories, describes how people show them (smiling, laughing, crying, frowning, shouting, shaking, hiding), knows a person can cry for joy and that boys and girls both have all feelings. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception.', '["picture of a face: which feeling","what a person does when feeling it","which feeling fits the story"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G3.SOCIAL.FAMILY_NEEDS_EMOTIONAL_N.EMOTIONAL_NEEDS', 'ENVI.G3.SOCIAL.FAMILY_NEEDS_EMOTIONAL_N', 'environmental_activities', 3, 'Describe ways in which emotional needs are met in real-life situations', ARRAY['ENVI.G3.SOCIAL.FAMILY_NEEDS_EMOTIONAL_N.b']::text[], 'Says that people need love, care, comfort, praise, being listened to and feeling safe, and describes how they are met: a hug, kind words, listening, playing together, praising good work, comforting someone who is sad; knows money and gifts alone do not meet them. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception.', '["which action meets an emotional need","what a sad child needs","need or not a need"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G3.SOCIAL.FOOD_IN_OUR_ENVIRONMENT.FOOD_GROUPS', 'ENVI.G3.SOCIAL.FOOD_IN_OUR_ENVIRONMENT', 'environmental_activities', 3, 'Identify common food items found locally and classify them into the three food groups', ARRAY['ENVI.G3.SOCIAL.FOOD_IN_OUR_ENVIRONMENT.a', 'ENVI.G3.SOCIAL.FOOD_IN_OUR_ENVIRONMENT.b']::text[], 'Names common local foods and puts them in the three food groups: energy-giving (ugali, rice, potatoes, cassava, bread, bananas for cooking), body-building (beans, meat, eggs, fish, milk, omena, ndengu) and protective (fruits and vegetables: sukuma wiki, cabbage, mangoes, oranges, carrots); knows a balanced meal has all three. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (ENVI.G3.RUBRIC.1.1), never as a phone question: c) observe table manners during meals.', '["which group a food belongs to","odd one out","picture sort into three groups"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G3.SOCIAL.OUR_COMMUNITY.SAFE_PLACES', 'ENVI.G3.SOCIAL.OUR_COMMUNITY', 'environmental_activities', 3, 'Identify ways of keeping safe in the community and classify places as safe or unsafe', ARRAY['ENVI.G3.SOCIAL.OUR_COMMUNITY.a', 'ENVI.G3.SOCIAL.OUR_COMMUNITY.b']::text[], 'Sorts places into safe (home, school, church or mosque, a police station, a hospital, a playground with adults) and unsafe (quarries, deep pits, open wells, rivers and dams, busy roads, dumping sites, abandoned buildings, near fallen electric wires), and names ways to keep safe: walk in groups, go straight home, do not go with or take gifts from strangers, keep away from fallen wires, tell a trusted adult. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception.', '["safe or unsafe place","what to do to keep safe","what to do if a stranger offers a gift"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G3.SOCIAL.OUR_COMMUNITY.ROAD_SIGNS', 'ENVI.G3.SOCIAL.OUR_COMMUNITY', 'environmental_activities', 3, 'Recognise basic road signs and say how to use them for personal safety', ARRAY['ENVI.G3.SOCIAL.OUR_COMMUNITY.c']::text[], 'Recognises the zebra crossing, the pedestrian crossing sign, the stop sign, traffic lights (red stop, amber get ready, green go for cars; the green walking figure for people) and the school-ahead sign, and says what a child does at each: wait, look right, left and right again, cross at the crossing, never run across. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception.', '["what a sign means","what to do at the sign","which sign shows a crossing"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G3.SOCIAL.CULTURAL_EVENTS.CULTURAL_EVENTS', 'ENVI.G3.SOCIAL.CULTURAL_EVENTS', 'environmental_activities', 3, 'Identify cultural events in the community and classify those that support social well-being and environmental care', ARRAY['ENVI.G3.SOCIAL.CULTURAL_EVENTS.a', 'ENVI.G3.SOCIAL.CULTURAL_EVENTS.b', 'ENVI.G3.SOCIAL.CULTURAL_EVENTS.c']::text[], 'Names cultural events in the community (weddings, naming ceremonies, harvest festivals, dowry ceremonies, funerals, tree-planting ceremonies, cultural days at school, community clean-ups) and sorts them: those that bring people together and help one another (social well-being) and those that care for the environment (tree planting, clean-ups, harvest thanksgiving); knows one event can do both. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception.', '["name a cultural event","does it bring people together or care for the environment","sort events"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G3.NATURA.WEATHER.BAD_WEATHER', 'ENVI.G3.NATURA.WEATHER', 'environmental_activities', 3, 'Describe unfavourable weather conditions, explain their dangers and say how to respond safely', ARRAY['ENVI.G3.NATURA.WEATHER.a', 'ENVI.G3.NATURA.WEATHER.b', 'ENVI.G3.NATURA.WEATHER.c']::text[], 'Describes unfavourable weather (very hot and dry, heavy rain and floods, strong winds, thunder and lightning, hailstones, very cold) and explains its dangers to people (drowning, being struck by lightning, sunburn and thirst, falling trees and roofs, colds and chest illness), and says the safe response: stay indoors in lightning, never shelter under a tall tree, never cross a flooded river, drink water and wear a hat in heat, wear warm clothes in cold. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception.', '["name the weather in the picture","what danger it brings","what to do"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G3.NATURA.SOIL.SOIL_TYPES', 'ENVI.G3.NATURA.SOIL', 'environmental_activities', 3, 'List the characteristics of different types of soil and say how soil is conserved', ARRAY['ENVI.G3.NATURA.SOIL.a']::text[], 'Lists characteristics of sand (rough, loose, big particles, light colour, water drains through fast), clay (smooth, sticky when wet, tiny particles, holds water, cracks when dry) and loam (dark, crumbly, a mixture, good for plants), and names soil conservation activities: mulching, manuring, planting trees and grass, and not leaving soil bare. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (ENVI.G3.RUBRIC.2.1), never as a phone question: b) carry out basic soil conservation activities in the environment.', '["which soil feels like this","which soil holds water","how to care for soil"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G3.NATURA.HEAT.HEAT_SOURCES', 'ENVI.G3.NATURA.HEAT', 'environmental_activities', 3, 'List sources of heat in the environment and identify their uses', ARRAY['ENVI.G3.NATURA.HEAT.a', 'ENVI.G3.NATURA.HEAT.b']::text[], 'Lists sources of heat (the sun, fire from firewood or charcoal, a gas or paraffin stove, electricity in a cooker, iron or kettle, the body) and identifies uses (cooking, warming the body and house, drying clothes and grain, ironing, boiling water), and knows ways to save heat: cover the pot, use an energy-saving jiko, put out the fire after cooking. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (ENVI.G3.RUBRIC.2.1), never as a phone question: c) carry out activities to conserve heat in the environment.', '["which one gives heat","what heat is used for here","match source and use"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G3.RESOUR.WATER.CLEAN_WATER', 'ENVI.G3.RESOUR.WATER', 'environmental_activities', 3, 'Name ways in which water is contaminated and how to make it clean and safe', ARRAY['ENVI.G3.RESOUR.WATER.a']::text[], 'Names ways water is contaminated (animals drinking and leaving dung, washing clothes and bathing in rivers, rubbish and human waste near water, chemicals, dirty containers and hands) and says how to make water clean and safe (boiling, filtering through sand and cloth, letting it settle, using a water treatment tablet as told by an adult, storing it covered); knows clear water can still carry germs. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (ENVI.G3.RUBRIC.3.1), never as a phone question: b) carry out activities to make water clean and safe; c) conserve water at home and school as a scarce resource.', '["how did this water get dirty","which water is safe to drink","how to make water safe"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G3.RESOUR.PLANTS.PLANT_SAFETY', 'ENVI.G3.RESOUR.PLANTS', 'environmental_activities', 3, 'Identify safety measures to observe when handling plants', ARRAY['ENVI.G3.RESOUR.PLANTS.a']::text[], 'Names safety measures with plants: do not eat unknown plants, berries or mushrooms; wear gloves or use a stick near thorns and stinging nettle; wash hands after handling plants; keep away from plants an adult says are poisonous (for example Sodom apple); tell an adult if pricked or if a plant makes the skin itch. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception.', '["is this safe to do","what to wear or use","what to do with an unknown berry"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G3.RESOUR.PLANTS.EDIBLE', 'ENVI.G3.RESOUR.PLANTS', 'environmental_activities', 3, 'Classify plants in the environment into edible and non-edible', ARRAY['ENVI.G3.RESOUR.PLANTS.b']::text[], 'Sorts local plants into edible (sukuma wiki, cabbage, spinach, maize, beans, cassava, bananas, mangoes, pawpaw, avocado, amaranth/terere) and non-edible (grass and weeds for people, Sodom apple, stinging nettle raw, flowers grown for beauty, trees for timber), and knows some edible plants are eaten only in one part or only cooked. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (ENVI.G3.RUBRIC.3.1), never as a phone question: c) make a kitchen garden using locally available materials.', '["edible or not edible","odd one out","which part we eat"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G3.RESOUR.ANIMALS.DOMESTIC_ANIMALS', 'ENVI.G3.RESOUR.ANIMALS', 'environmental_activities', 3, 'Explain the importance of domestic animals and determine ways of caring for them', ARRAY['ENVI.G3.RESOUR.ANIMALS.a', 'ENVI.G3.RESOUR.ANIMALS.b']::text[], 'Explains why domestic animals matter (milk, meat, eggs, skins and wool, manure, ploughing and carrying loads by oxen and donkeys, guarding by dogs, catching rats by cats, money from selling) and names ways of caring for them: food, clean water, a clean dry shelter, treating them when sick (by a vet), not beating or overloading them. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (ENVI.G3.RUBRIC.3.1), never as a phone question: c) engage in activities that care for domestic animals.', '["what this animal gives us","how to care for it","which is cruel and which is caring"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G3.RESOUR.WASTE_MATERIALS.WASTE_INCOME', 'ENVI.G3.RESOUR.WASTE_MATERIALS', 'environmental_activities', 3, 'Identify waste materials that can generate income and describe how', ARRAY['ENVI.G3.RESOUR.WASTE_MATERIALS.a', 'ENVI.G3.RESOUR.WASTE_MATERIALS.b']::text[], 'Names waste that can bring money (plastic bottles, scrap metal, paper and cartons, tins, old tyres, glass bottles collected by an adult, kitchen waste for compost, banana fibres, old clothes) and describes how: selling to collectors and recyclers, making items to sell (mats, baskets, toys, tyre sandals, paper bags), making manure to sell; knows sharp, broken or medical waste is never picked by children. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (ENVI.G3.RUBRIC.3.1), never as a phone question: c) carry out activities to manage waste materials in the environment.', '["which waste can earn money","how it earns money","safe or unsafe to pick"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G3.SOCIAL.OUR_LIVING_ENVIRONMENT.BEDDING', 'ENVI.G2.SOCIAL.OUR_HOME.a', 'outcome', 'essential', 'Personal and common items at home: bedding is a personal item. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G3.SOCIAL.OUR_LIVING_ENVIRONMENT.BEDDING', 'ENVI.G2.SOCIAL.OUR_HOME.b', 'outcome', 'essential', 'Materials for cleaning personal items are used again for bedding. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G3.SOCIAL.OUR_LIVING_ENVIRONMENT.BEDDING', 'ENVI.G1.SOCIAL.OUR_HOME.a', 'outcome', 'essential', 'Cleaning materials for a home come before cleaning a sleeping area. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G3.SOCIAL.FAMILY_NEEDS_EMOTIONAL_N.FEELINGS', 'ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS.a', 'outcome', 'essential', 'Needs and wants come before the emotional needs of a family. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G3.SOCIAL.FAMILY_NEEDS_EMOTIONAL_N.FEELINGS', 'ENVI.G1.SOCIAL.FAMILY_NEEDS.a', 'outcome', 'essential', 'Basic needs of a family, which emotional needs add to. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G3.SOCIAL.FAMILY_NEEDS_EMOTIONAL_N.EMOTIONAL_NEEDS', 'ENVI.G3.SOCIAL.FAMILY_NEEDS_EMOTIONAL_N.FEELINGS', 'skill', 'essential', 'Naming a feeling comes before knowing what the person needs. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G3.SOCIAL.FAMILY_NEEDS_EMOTIONAL_N.EMOTIONAL_NEEDS', 'ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS.c', 'outcome', 'essential', 'Sorting needs from wants comes before naming emotional needs. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G3.SOCIAL.FOOD_IN_OUR_ENVIRONMENT.FOOD_GROUPS', 'ENVI.G2.RESOUR.ANIMALS.a', 'outcome', 'essential', 'Food items from animals: most are body-building foods. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G3.SOCIAL.FOOD_IN_OUR_ENVIRONMENT.FOOD_GROUPS', 'ENVI.G1.SOCIAL.FAMILY_NEEDS.c', 'outcome', 'essential', 'Food from plants and animals comes before the three food groups. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G3.SOCIAL.FOOD_IN_OUR_ENVIRONMENT.FOOD_GROUPS', 'ENVI.G1.SOCIAL.OUR_MARKET.c', 'outcome', 'essential', 'Sorting fruits and vegetables: the protective group. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G3.SOCIAL.OUR_COMMUNITY.SAFE_PLACES', 'ENVI.G2.SOCIAL.OUR_SCHOOL.b', 'outcome', 'essential', 'Common accidents at school come before dangers in the wider community. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G3.SOCIAL.OUR_COMMUNITY.SAFE_PLACES', 'ENVI.G1.SOCIAL.OUR_SCHOOL.c', 'outcome', 'essential', 'Personal safety on the way to school. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G3.SOCIAL.OUR_COMMUNITY.SAFE_PLACES', 'ENVI.G1.SOCIAL.OUR_HOME.b', 'outcome', 'essential', 'Common accidents at home. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G3.SOCIAL.OUR_COMMUNITY.ROAD_SIGNS', 'ENVI.G2.SOCIAL.OUR_MARKET.a', 'outcome', 'essential', 'Features on the way to the market, including the road and its parts. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G3.SOCIAL.OUR_COMMUNITY.ROAD_SIGNS', 'ENVI.G1.SOCIAL.OUR_SCHOOL.c', 'outcome', 'essential', 'Safety on the way to school, where roads are crossed. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
