INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G3.RESOUR.ANIMALS.DOMESTIC_ANIMALS', 'ENVI.G2.RESOUR.ANIMALS.c', 'outcome', 'essential', 'Caring for animals in the locality, practised in Grade 2. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G3.RESOUR.ANIMALS.DOMESTIC_ANIMALS', 'ENVI.G2.RESOUR.ANIMALS.b', 'outcome', 'essential', 'Relating food items to the animals that give them. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
