INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G3.RESOUR.WASTE_MATERIALS.WASTE_INCOME', 'ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS.c', 'outcome', 'essential', 'Needs, wants and money: the start of financial literacy. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.SOCIAL.OUR_LIVING_ENVIRONMENT.BEDDING.M_E3_BED_ONLY_MATTRESS', 'ENVI.G3.SOCIAL.OUR_LIVING_ENVIRONMENT.BEDDING', 'Thinks only a bought mattress counts as bedding, not a mat, reeds or a gunny-bag mattress.', '{"question":"Which of these can be used as bedding? A sisal mat, a cooking pot, a spoon.","wrong_answer":"None of them, bedding is a mattress","correct_answer":"A sisal mat"}'::jsonb, 'The child has seen bedding sold in shops and links the word only with a mattress.', 'Offer "None of them, bedding is a mattress" beside "A sisal mat" and ask the child to choose.', 'Show a mat, a blanket and a gunny-bag mattress. Ask: can you sleep on it or under it? Then it is bedding.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.SOCIAL.OUR_LIVING_ENVIRONMENT.BEDDING.M_E3_BED_WASH_NEVER', 'ENVI.G3.SOCIAL.OUR_LIVING_ENVIRONMENT.BEDDING', 'Thinks bedding that looks clean never needs washing or airing.', '{"question":"Wanjiru''s blanket looks clean. Should she still put it in the sun sometimes?","wrong_answer":"No, it looks clean","correct_answer":"Yes, sun and air kill germs and remove smells"}'::jsonb, 'Children judge clean by what they can see; germs and sweat cannot be seen.', 'Offer "No, it looks clean" beside "Yes, sun and air kill germs and remove smells" and ask the child to choose.', 'Smell a blanket aired in the sun and one kept folded for weeks. Say: germs hide where we cannot see.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.SOCIAL.OUR_LIVING_ENVIRONMENT.BEDDING.M_E3_BED_FOOD_OK', 'ENVI.G3.SOCIAL.OUR_LIVING_ENVIRONMENT.BEDDING', 'Thinks eating on the bed is fine as long as the crumbs are shaken off.', '{"question":"Where should we eat our food?","wrong_answer":"On the bed, then shake it","correct_answer":"At the table or on a mat, away from the bed"}'::jsonb, 'Eating in bed is common at home and nothing bad seems to follow at once.', 'Offer "On the bed, then shake it" beside "At the table or on a mat, away from the bed" and ask the child to choose.', 'Show how crumbs bring ants, cockroaches and rats. Agree: food stays away from where we sleep.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.SOCIAL.OUR_LIVING_ENVIRONMENT.BEDDING.M_E3_BED_WET_HIDE', 'ENVI.G3.SOCIAL.OUR_LIVING_ENVIRONMENT.BEDDING', 'Thinks wet bedding after bedwetting should be folded and hidden so nobody knows.', '{"question":"A child wets the bed at night. What should be done with the wet bedding?","wrong_answer":"Fold it and hide it","correct_answer":"Wash it or put it in the sun to dry, and the child washes"}'::jsonb, 'The child fears shame, so hiding feels safest.', 'Offer "Fold it and hide it" beside "Wash it or put it in the sun to dry, and the child washes" and ask the child to choose.', 'Say calmly that many children wet the bed. Wet bedding is washed and dried in the sun; the child bathes. No one is laughed at.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.SOCIAL.FAMILY_NEEDS_EMOTIONAL_N.FEELINGS.M_E3_FEEL_BOYS_NO_CRY', 'ENVI.G3.SOCIAL.FAMILY_NEEDS_EMOTIONAL_N.FEELINGS', 'Thinks boys do not feel sad or cry, so a crying boy is weak.', '{"question":"Otieno falls and cries. What is he feeling?","wrong_answer":"Nothing, boys do not cry","correct_answer":"Pain or sadness: boys feel sad and cry too"}'::jsonb, 'The child has heard "boys don''t cry" at home or in play.', 'Offer "Nothing, boys do not cry" beside "Pain or sadness: boys feel sad and cry too" and ask the child to choose.', 'Read a story where a father cries at good news. Say: everyone has feelings, boys and girls.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.SOCIAL.FAMILY_NEEDS_EMOTIONAL_N.FEELINGS.M_E3_FEEL_TEARS_SAD', 'ENVI.G3.SOCIAL.FAMILY_NEEDS_EMOTIONAL_N.FEELINGS', 'Thinks tears always mean sadness.', '{"question":"Grandmother cries when her son comes home after many years. How does she feel?","wrong_answer":"Sad","correct_answer":"Happy (tears of joy)"}'::jsonb, 'Most tears the child has seen came with sadness or pain.', 'Offer "Sad" beside "Happy (tears of joy)" and ask the child to choose.', 'Show a picture of a happy reunion with tears. Ask what made her cry, then name joy.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.SOCIAL.FAMILY_NEEDS_EMOTIONAL_N.FEELINGS.M_E3_FEEL_ANGRY_BAD', 'ENVI.G3.SOCIAL.FAMILY_NEEDS_EMOTIONAL_N.FEELINGS', 'Thinks feeling angry makes someone a bad person.', '{"question":"Achieng feels angry when her book is torn. Is Achieng a bad girl?","wrong_answer":"Yes, she is angry so she is bad","correct_answer":"No, feeling angry is normal; what matters is what she does next"}'::jsonb, 'Children are often punished when angry, so the feeling itself seems wrong.', 'Offer "Yes, she is angry so she is bad" beside "No, feeling angry is normal; what matters is what she does next" and ask the child to choose.', 'Separate the feeling from the action: angry is fine, hitting is not. Practise calm steps: breathe, tell an adult.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.SOCIAL.FAMILY_NEEDS_EMOTIONAL_N.FEELINGS.M_E3_FEEL_FACE_ONLY', 'ENVI.G3.SOCIAL.FAMILY_NEEDS_EMOTIONAL_N.FEELINGS', 'Looks only at the mouth to name a feeling, so a forced smile or a frightened face with an open mouth is misread.', '{"question":"A child stands shaking with wide eyes and an open mouth while a dog barks. How does she feel?","wrong_answer":"Happy, her mouth is open","correct_answer":"Afraid"}'::jsonb, 'Young children first learn feelings from smiley and sad mouth drawings.', 'Offer "Happy, her mouth is open" beside "Afraid" and ask the child to choose.', 'Look at eyes, hands and body as well as the mouth. Act out afraid with the whole body.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.SOCIAL.FAMILY_NEEDS_EMOTIONAL_N.EMOTIONAL_NEEDS.M_E3_EMO_GIFTS', 'ENVI.G3.SOCIAL.FAMILY_NEEDS_EMOTIONAL_N.EMOTIONAL_NEEDS', 'Thinks giving things (sweets, money, toys) is the way to meet every emotional need.', '{"question":"Baraka is sad because his grandfather is sick. What will help him most?","wrong_answer":"Give him sweets","correct_answer":"Sit with him, listen and comfort him"}'::jsonb, 'Children see gifts given at happy times and think gifts fix feelings.', 'Offer "Give him sweets" beside "Sit with him, listen and comfort him" and ask the child to choose.', 'Role-play two ways to help a sad friend: a sweet and walking away, or listening. Ask which felt better.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.SOCIAL.FAMILY_NEEDS_EMOTIONAL_N.EMOTIONAL_NEEDS.M_E3_EMO_ONLY_FOOD', 'ENVI.G3.SOCIAL.FAMILY_NEEDS_EMOTIONAL_N.EMOTIONAL_NEEDS', 'Thinks needs are only food, clothes and shelter, so love is not a need.', '{"question":"Is love a need?","wrong_answer":"No, only food, clothes and a house are needs","correct_answer":"Yes, love and care are emotional needs"}'::jsonb, 'Grade 1 and 2 taught basic needs as things you can touch.', 'Offer "No, only food, clothes and a house are needs" beside "Yes, love and care are emotional needs" and ask the child to choose.', 'Add a fourth column to the needs chart: love, care, praise. Say: we need these to grow well inside.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.SOCIAL.FAMILY_NEEDS_EMOTIONAL_N.EMOTIONAL_NEEDS.M_E3_EMO_ADULTS_ONLY', 'ENVI.G3.SOCIAL.FAMILY_NEEDS_EMOTIONAL_N.EMOTIONAL_NEEDS', 'Thinks only small babies need comfort and care, not big children or adults.', '{"question":"Mother is tired and sad after a long day. What can a child do?","wrong_answer":"Nothing, adults do not need comfort","correct_answer":"Greet her kindly, help her and give her a hug"}'::jsonb, 'The child sees comfort given mostly to babies.', 'Offer "Nothing, adults do not need comfort" beside "Greet her kindly, help her and give her a hug" and ask the child to choose.', 'Tell a story of a child who comforts a parent. Everyone needs love, at every age.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.SOCIAL.FAMILY_NEEDS_EMOTIONAL_N.EMOTIONAL_NEEDS.M_E3_EMO_PRAISE_SPOIL', 'ENVI.G3.SOCIAL.FAMILY_NEEDS_EMOTIONAL_N.EMOTIONAL_NEEDS', 'Thinks praising someone makes them proud, so good work should not be praised.', '{"question":"Akinyi sweeps the class well. What should the teacher say?","wrong_answer":"Nothing, praise makes her proud","correct_answer":"Well done, thank you"}'::jsonb, 'The child has heard adults warn against "spoiling" children.', 'Offer "Nothing, praise makes her proud" beside "Well done, thank you" and ask the child to choose.', 'Show how praise makes a classmate want to help again. Praise the action, kindly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.SOCIAL.FOOD_IN_OUR_ENVIRONMENT.FOOD_GROUPS.M_E3_FOOD_UGALI_BODY', 'ENVI.G3.SOCIAL.FOOD_IN_OUR_ENVIRONMENT.FOOD_GROUPS', 'Puts ugali in the body-building group because it makes one strong and full.', '{"question":"Which group does ugali belong to?","wrong_answer":"Body-building","correct_answer":"Energy-giving"}'::jsonb, 'Adults say "eat ugali to grow strong", and the child links strong with body-building.', 'Offer "Body-building" beside "Energy-giving" and ask the child to choose.', 'Say: ugali gives energy to run and play. Beans and eggs build the body. Sort a plate of ugali, beans and sukuma.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.SOCIAL.FOOD_IN_OUR_ENVIRONMENT.FOOD_GROUPS.M_E3_FOOD_FRUIT_SWEET', 'ENVI.G3.SOCIAL.FOOD_IN_OUR_ENVIRONMENT.FOOD_GROUPS', 'Thinks protective foods are only sweet fruits, so vegetables like sukuma wiki are not protective.', '{"question":"Is sukuma wiki a protective food?","wrong_answer":"No, protective foods are sweet fruits","correct_answer":"Yes, vegetables and fruits are protective foods"}'::jsonb, 'Fruits are taught as healthy treats; greens are eaten as a side dish.', 'Offer "No, protective foods are sweet fruits" beside "Yes, vegetables and fruits are protective foods" and ask the child to choose.', 'Put sukuma, cabbage, mango and orange in one basket labelled protective. Say: they help us fight disease.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.SOCIAL.FOOD_IN_OUR_ENVIRONMENT.FOOD_GROUPS.M_E3_FOOD_MILK_DRINK', 'ENVI.G3.SOCIAL.FOOD_IN_OUR_ENVIRONMENT.FOOD_GROUPS', 'Thinks milk is a drink, not a food, so it has no food group.', '{"question":"Which group does milk belong to?","wrong_answer":"None, milk is only a drink","correct_answer":"Body-building"}'::jsonb, 'Milk is poured into a cup like water or tea.', 'Offer "None, milk is only a drink" beside "Body-building" and ask the child to choose.', 'Show that milk comes from a cow like meat and helps babies grow. It is a body-building food.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.SOCIAL.FOOD_IN_OUR_ENVIRONMENT.FOOD_GROUPS.M_E3_FOOD_ONE_GROUP', 'ENVI.G3.SOCIAL.FOOD_IN_OUR_ENVIRONMENT.FOOD_GROUPS', 'Thinks a full plate of one food (a big plate of rice) is a good meal.', '{"question":"Which meal is balanced? A: rice only. B: rice, beans and cabbage.","wrong_answer":"A, it fills you","correct_answer":"B, it has all three food groups"}'::jsonb, 'Being full is the child''s sign of a good meal.', 'Offer "A, it fills you" beside "B, it has all three food groups" and ask the child to choose.', 'Draw a plate in three parts. Fill each part with one group. Say: a good meal has all three.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.SOCIAL.OUR_COMMUNITY.SAFE_PLACES.M_E3_SAFE_STRANGER_KIND', 'ENVI.G3.SOCIAL.OUR_COMMUNITY.SAFE_PLACES', 'Thinks a stranger who is kind or offers sweets is safe to go with.', '{"question":"A kind stranger offers you sweets and a ride home. What should you do?","wrong_answer":"Go with him, he is kind","correct_answer":"Say no, walk away and tell a trusted adult"}'::jsonb, 'Children judge people by how nice they seem.', 'Offer "Go with him, he is kind" beside "Say no, walk away and tell a trusted adult" and ask the child to choose.', 'Role-play saying "No, thank you" and walking to a trusted adult. Kind words do not make a stranger safe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.SOCIAL.OUR_COMMUNITY.SAFE_PLACES.M_E3_SAFE_WATER_FUN', 'ENVI.G3.SOCIAL.OUR_COMMUNITY.SAFE_PLACES', 'Thinks a river or dam is a safe place to play if you can stand in it.', '{"question":"Is a dam a safe place to play without an adult?","wrong_answer":"Yes, if the water is not deep","correct_answer":"No, it is unsafe: water can be deep and you can drown"}'::jsonb, 'The edge looks shallow and the child cannot see the deep part.', 'Offer "Yes, if the water is not deep" beside "No, it is unsafe: water can be deep and you can drown" and ask the child to choose.', 'Show a picture of a dam with a hidden deep middle. Rule: no water play without an adult.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.SOCIAL.OUR_COMMUNITY.SAFE_PLACES.M_E3_SAFE_WIRE_TOUCH', 'ENVI.G3.SOCIAL.OUR_COMMUNITY.SAFE_PLACES', 'Thinks a fallen electric wire is safe to touch or play with if it is not sparking.', '{"question":"You see a wire lying on the ground after a storm. What should you do?","wrong_answer":"Pick it up and move it","correct_answer":"Keep far away and tell an adult"}'::jsonb, 'A wire looks like a rope; the danger cannot be seen.', 'Offer "Pick it up and move it" beside "Keep far away and tell an adult" and ask the child to choose.', 'Say: a fallen wire can kill even when quiet. Stay far, tell an adult to call Kenya Power.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.SOCIAL.OUR_COMMUNITY.SAFE_PLACES.M_E3_SAFE_KNOWN_ALWAYS', 'ENVI.G3.SOCIAL.OUR_COMMUNITY.SAFE_PLACES', 'Thinks danger only comes from strangers, so any known person can ask them to keep secrets.', '{"question":"A neighbour asks you to keep a secret touch from your parents. What should you do?","wrong_answer":"Keep the secret, he is not a stranger","correct_answer":"Tell a trusted adult at once"}'::jsonb, 'Children are told only "beware of strangers".', 'Offer "Keep the secret, he is not a stranger" beside "Tell a trusted adult at once" and ask the child to choose.', 'Teach the rule: no secret about touching, from anyone. Name trusted adults at home and school.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.SOCIAL.OUR_COMMUNITY.ROAD_SIGNS.M_E3_ROAD_ZEBRA_SAFE', 'ENVI.G3.SOCIAL.OUR_COMMUNITY.ROAD_SIGNS', 'Thinks a zebra crossing means cars will always stop, so you can cross without looking.', '{"question":"You reach a zebra crossing. What do you do?","wrong_answer":"Cross at once, cars must stop","correct_answer":"Stop, look right, left and right again, and cross when cars have stopped"}'::jsonb, 'The child is told the crossing is "for people" and thinks it protects by itself.', 'Offer "Cross at once, cars must stop" beside "Stop, look right, left and right again, and cross when cars have stopped" and ask the child to choose.', 'Practise at a chalk crossing: stop, look, wait for cars to stop, then walk.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.SOCIAL.OUR_COMMUNITY.ROAD_SIGNS.M_E3_ROAD_GREEN_PEOPLE', 'ENVI.G3.SOCIAL.OUR_COMMUNITY.ROAD_SIGNS', 'Thinks the green traffic light for cars means people may cross.', '{"question":"The traffic light for cars is green. Can you cross?","wrong_answer":"Yes, green means go","correct_answer":"No, green means cars go; wait"}'::jsonb, 'Green means go in every game the child knows.', 'Offer "Yes, green means go" beside "No, green means cars go; wait" and ask the child to choose.', 'Show both lights: green for cars means cars move. People cross when the walking figure is green.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.SOCIAL.OUR_COMMUNITY.ROAD_SIGNS.M_E3_ROAD_LOOK_ONE', 'ENVI.G3.SOCIAL.OUR_COMMUNITY.ROAD_SIGNS', 'Looks only one way before crossing.', '{"question":"Before crossing a road in Kenya, which way do you look first?","wrong_answer":"Only left","correct_answer":"Right, then left, then right again"}'::jsonb, 'The child copies others who glance once.', 'Offer "Only left" beside "Right, then left, then right again" and ask the child to choose.', 'Practise "right, left, right" aloud at a chalk road. In Kenya cars drive on the left, so the near cars come from the right.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.SOCIAL.OUR_COMMUNITY.ROAD_SIGNS.M_E3_ROAD_STOP_PEOPLE', 'ENVI.G3.SOCIAL.OUR_COMMUNITY.ROAD_SIGNS', 'Thinks the stop sign tells people walking to stop and never cross.', '{"question":"Who must stop at a stop sign?","wrong_answer":"Only people walking","correct_answer":"Drivers (and everyone must take care)"}'::jsonb, 'The child sees the word stop and takes it as an order for himself.', 'Offer "Only people walking" beside "Drivers (and everyone must take care)" and ask the child to choose.', 'Show the stop sign at a junction from a driver''s seat drawing. Drivers stop, people still look before crossing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.SOCIAL.CULTURAL_EVENTS.CULTURAL_EVENTS.M_E3_CULT_PARTY_ONLY', 'ENVI.G3.SOCIAL.CULTURAL_EVENTS.CULTURAL_EVENTS', 'Thinks a cultural event is only a party with music and food.', '{"question":"Is a tree-planting ceremony a cultural event?","wrong_answer":"No, there is no party","correct_answer":"Yes, it is an event the community does together"}'::jsonb, 'Events the child has seen were celebrations with food.', 'Offer "No, there is no party" beside "Yes, it is an event the community does together" and ask the child to choose.', 'List events with and without parties. Say: a cultural event is what a community does together by its ways.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.SOCIAL.CULTURAL_EVENTS.CULTURAL_EVENTS.M_E3_CULT_ENV_NONE', 'ENVI.G3.SOCIAL.CULTURAL_EVENTS.CULTURAL_EVENTS', 'Thinks cultural events have nothing to do with caring for the environment.', '{"question":"Which event cares for the environment?","wrong_answer":"A wedding, because people dance","correct_answer":"A tree-planting ceremony (a clean-up day)"}'::jsonb, 'Caring for the environment is taught in science lessons, not with culture.', 'Offer "A wedding, because people dance" beside "A tree-planting ceremony (a clean-up day)" and ask the child to choose.', 'Show pictures of a tree planted at a naming or a clean-up after a harvest feast. Sort them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.SOCIAL.CULTURAL_EVENTS.CULTURAL_EVENTS.M_E3_CULT_ONE_PURPOSE', 'ENVI.G3.SOCIAL.CULTURAL_EVENTS.CULTURAL_EVENTS', 'Thinks an event can only do one thing, so it is either social or environmental.', '{"question":"A school cultural day ends with everyone planting trees. What does it do?","wrong_answer":"Only brings people together","correct_answer":"Both: brings people together and cares for the environment"}'::jsonb, 'Sorting into two boxes makes the child think each item fits only one.', 'Offer "Only brings people together" beside "Both: brings people together and cares for the environment" and ask the child to choose.', 'Use a Venn diagram: social well-being, environmental care, both in the middle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.SOCIAL.CULTURAL_EVENTS.CULTURAL_EVENTS.M_E3_CULT_OTHERS_WRONG', 'ENVI.G3.SOCIAL.CULTURAL_EVENTS.CULTURAL_EVENTS', 'Thinks other communities'' events are strange or wrong because they differ from his own.', '{"question":"A classmate''s community has a different naming ceremony. What should we think?","wrong_answer":"It is wrong because it is not like ours","correct_answer":"It is their way; we can learn about it and respect it"}'::jsonb, 'Children see their own ways as the normal ones.', 'Offer "It is wrong because it is not like ours" beside "It is their way; we can learn about it and respect it" and ask the child to choose.', 'Invite children to share events from their communities. Find what all of them have in common: bringing people together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.NATURA.WEATHER.BAD_WEATHER.M_E3_WEA_TREE_SHELTER', 'ENVI.G3.NATURA.WEATHER.BAD_WEATHER', 'Thinks a tall tree is the best shelter in a thunderstorm.', '{"question":"It starts to thunder and rain while you walk home. Where do you go?","wrong_answer":"Under the tallest tree","correct_answer":"Into a building, away from tall trees"}'::jsonb, 'A tree keeps you dry from rain, so it seems safe in any storm.', 'Offer "Under the tallest tree" beside "Into a building, away from tall trees" and ask the child to choose.', 'Show that lightning strikes the tallest thing. Practise going into a building or crouching low in the open.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.NATURA.WEATHER.BAD_WEATHER.M_E3_WEA_FLOOD_CROSS', 'ENVI.G3.NATURA.WEATHER.BAD_WEATHER', 'Thinks moving floodwater is safe to cross if it only reaches the knees.', '{"question":"A small river is flooded up to your knees on the way to school. What do you do?","wrong_answer":"Walk across quickly","correct_answer":"Do not cross; go back or wait for an adult"}'::jsonb, 'The water looks shallow and the child cannot see its force.', 'Offer "Walk across quickly" beside "Do not cross; go back or wait for an adult" and ask the child to choose.', 'Show how a little moving water can push over a child. Rule: turn back, wait for an adult.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.NATURA.WEATHER.BAD_WEATHER.M_E3_WEA_HOT_GOOD', 'ENVI.G3.NATURA.WEATHER.BAD_WEATHER', 'Thinks hot sunny weather can never be unfavourable because sunshine is good.', '{"question":"Can very hot weather be dangerous?","wrong_answer":"No, sunshine is always good","correct_answer":"Yes, it can cause thirst, sunburn and drought"}'::jsonb, 'Sunny is called "good weather" in songs and greetings.', 'Offer "No, sunshine is always good" beside "Yes, it can cause thirst, sunburn and drought" and ask the child to choose.', 'Talk about a drought: dry rivers, dying crops and thirst. Name the safe actions: water, shade, hat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.NATURA.WEATHER.BAD_WEATHER.M_E3_WEA_LIGHTNING_PHONE', 'ENVI.G3.NATURA.WEATHER.BAD_WEATHER', 'Thinks lightning is only dangerous when it is raining hard, so playing outside during distant thunder is fine.', '{"question":"You hear thunder but it is not raining yet. Can you keep playing football in the field?","wrong_answer":"Yes, until the rain comes","correct_answer":"No, go indoors when you hear thunder"}'::jsonb, 'The child links danger with rain, which can be felt, not with thunder.', 'Offer "Yes, until the rain comes" beside "No, go indoors when you hear thunder" and ask the child to choose.', 'Teach the rule: when thunder roars, go indoors. Lightning can strike before the rain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.NATURA.SOIL.SOIL_TYPES.M_E3_SOIL_ALL_SAME', 'ENVI.G3.NATURA.SOIL.SOIL_TYPES', 'Thinks all soil is the same and differs only in colour.', '{"question":"Is sand the same as clay soil?","wrong_answer":"Yes, soil is soil","correct_answer":"No, sand is rough and loose, clay is smooth and sticky"}'::jsonb, 'Soil looks like one brown material from a distance.', 'Offer "Yes, soil is soil" beside "No, sand is rough and loose, clay is smooth and sticky" and ask the child to choose.', 'Let the child rub sand and clay between the fingers and roll each wet. Name the feel.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.NATURA.SOIL.SOIL_TYPES.M_E3_SOIL_CLAY_DRAIN', 'ENVI.G3.NATURA.SOIL.SOIL_TYPES', 'Thinks water drains fastest through clay because it is soft.', '{"question":"Water is poured on sand and on clay. Which lets water through faster?","wrong_answer":"Clay","correct_answer":"Sand"}'::jsonb, 'Soft things seem to soak and let through more.', 'Offer "Clay" beside "Sand" and ask the child to choose.', 'Pour water through sand and clay in two bottles with holes. Count how fast it drips.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.NATURA.SOIL.SOIL_TYPES.M_E3_SOIL_SAND_PLANTS', 'ENVI.G3.NATURA.SOIL.SOIL_TYPES', 'Thinks sand is the best soil for plants because it is clean.', '{"question":"Which soil is best for growing vegetables?","wrong_answer":"Sand","correct_answer":"Loam"}'::jsonb, 'Sand looks clean and nice, so it seems good.', 'Offer "Sand" beside "Loam" and ask the child to choose.', 'Grow beans in sand, clay and loam pots. Watch which grows best. Name loam.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.NATURA.SOIL.SOIL_TYPES.M_E3_SOIL_BARE_GOOD', 'ENVI.G3.NATURA.SOIL.SOIL_TYPES', 'Thinks bare, swept soil is good for the environment and mulch is just rubbish.', '{"question":"Which garden protects the soil better: bare soil or soil covered with dry grass?","wrong_answer":"Bare soil, it is clean","correct_answer":"Soil covered with dry grass (mulch)"}'::jsonb, 'Children sweep compounds bare, so bare looks tidy and right.', 'Offer "Bare soil, it is clean" beside "Soil covered with dry grass (mulch)" and ask the child to choose.', 'Pour water on a bare tray and a mulched tray of soil. See which washes away.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.NATURA.HEAT.HEAT_SOURCES.M_E3_HEAT_LIGHT_SAME', 'ENVI.G3.NATURA.HEAT.HEAT_SOURCES', 'Thinks everything that gives light gives heat, so a torch or a phone screen is a heat source.', '{"question":"Which is a source of heat: a torch or a charcoal jiko?","wrong_answer":"The torch","correct_answer":"The charcoal jiko"}'::jsonb, 'Light and heat came together in the sun and fire the child knows.', 'Offer "The torch" beside "The charcoal jiko" and ask the child to choose.', 'Hold a hand near a torch and near a warm jiko (safely). Feel which is warm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.NATURA.HEAT.HEAT_SOURCES.M_E3_HEAT_SUN_ONLY_LIGHT', 'ENVI.G3.NATURA.HEAT.HEAT_SOURCES', 'Thinks the sun gives only light, not heat.', '{"question":"Why do clothes dry when hung in the sun?","wrong_answer":"Because of the wind only","correct_answer":"The sun gives heat that dries them"}'::jsonb, 'The sun is taught first as giving day and light.', 'Offer "Because of the wind only" beside "The sun gives heat that dries them" and ask the child to choose.', 'Put two wet cloths, one in sun and one in shade. Feel and compare after an hour.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.NATURA.HEAT.HEAT_SOURCES.M_E3_HEAT_COVER_NO', 'ENVI.G3.NATURA.HEAT.HEAT_SOURCES', 'Thinks covering a cooking pot does not matter for saving heat.', '{"question":"Which pot of water boils faster: covered or uncovered?","wrong_answer":"Uncovered, so we can see it","correct_answer":"Covered, the lid keeps the heat in"}'::jsonb, 'An open pot lets the cook watch, so it seems better.', 'Offer "Uncovered, so we can see it" beside "Covered, the lid keeps the heat in" and ask the child to choose.', 'Boil two small pots, one covered. Time them. Say: the lid keeps heat in and saves fuel.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.NATURA.HEAT.HEAT_SOURCES.M_E3_HEAT_FIRE_LEAVE', 'ENVI.G3.NATURA.HEAT.HEAT_SOURCES', 'Thinks a fire can be left burning after cooking because it will go out by itself.', '{"question":"Cooking is finished. What should be done with the fire?","wrong_answer":"Leave it, it will go out","correct_answer":"Put it out safely to save fuel and prevent burns"}'::jsonb, 'The child has seen fires die down slowly on their own.', 'Offer "Leave it, it will go out" beside "Put it out safely to save fuel and prevent burns" and ask the child to choose.', 'Show how embers can flare up and burn. An adult puts out the fire; children keep away.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.RESOUR.WATER.CLEAN_WATER.M_E3_WAT_CLEAR_SAFE', 'ENVI.G3.RESOUR.WATER.CLEAN_WATER', 'Thinks water that looks clear is always safe to drink.', '{"question":"River water looks clear. Is it safe to drink straight away?","wrong_answer":"Yes, it is clear","correct_answer":"No, it may have germs; boil it first"}'::jsonb, 'The child judges water by colour; germs are invisible.', 'Offer "Yes, it is clear" beside "No, it may have germs; boil it first" and ask the child to choose.', 'Show clear water under a hand lens or a picture of germs. Rule: boil drinking water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.RESOUR.WATER.CLEAN_WATER.M_E3_WAT_FILTER_GERMS', 'ENVI.G3.RESOUR.WATER.CLEAN_WATER', 'Thinks a sand filter makes water fully safe to drink.', '{"question":"Water has gone through a sand and cloth filter. What else should be done before drinking?","wrong_answer":"Nothing, it is clean now","correct_answer":"Boil it"}'::jsonb, 'The filtered water looks clean, so the job seems done.', 'Offer "Nothing, it is clean now" beside "Boil it" and ask the child to choose.', 'Filter muddy water: it looks clear. Say: the filter removes dirt, boiling kills germs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.RESOUR.WATER.CLEAN_WATER.M_E3_WAT_WASH_RIVER', 'ENVI.G3.RESOUR.WATER.CLEAN_WATER', 'Thinks washing clothes or cows in a river does not dirty the water because the water flows away.', '{"question":"People wash clothes in a river upstream. Is the water downstream clean?","wrong_answer":"Yes, the dirt flows away","correct_answer":"No, the soap and dirt flow down to people below"}'::jsonb, 'Moving water seems to carry dirt away and disappear.', 'Offer "Yes, the dirt flows away" beside "No, the soap and dirt flow down to people below" and ask the child to choose.', 'Draw a river with a village upstream and a school downstream. Follow the soap with a finger.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.RESOUR.WATER.CLEAN_WATER.M_E3_WAT_COVER_NO', 'ENVI.G3.RESOUR.WATER.CLEAN_WATER', 'Thinks a water container can be left open if the water was clean when it was put in.', '{"question":"You have boiled water. How should you keep it?","wrong_answer":"In an open bucket","correct_answer":"In a clean, covered container"}'::jsonb, 'Once clean, water seems to stay clean.', 'Offer "In an open bucket" beside "In a clean, covered container" and ask the child to choose.', 'Leave an open cup in class for a day. See dust and insects. Cover the other.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.RESOUR.PLANTS.PLANT_SAFETY.M_E3_PLT_BERRY_TASTE', 'ENVI.G3.RESOUR.PLANTS.PLANT_SAFETY', 'Thinks a small taste of an unknown berry is fine to check if it is food.', '{"question":"You find red berries on a bush. What should you do?","wrong_answer":"Taste one to check","correct_answer":"Do not taste; ask an adult first"}'::jsonb, 'Children explore by tasting, and many berries look like fruit.', 'Offer "Taste one to check" beside "Do not taste; ask an adult first" and ask the child to choose.', 'Show pictures of a safe and a poisonous berry that look alike. Rule: never taste, ask an adult.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.RESOUR.PLANTS.PLANT_SAFETY.M_E3_PLT_BRIGHT_SAFE', 'ENVI.G3.RESOUR.PLANTS.PLANT_SAFETY', 'Thinks brightly coloured or nice-smelling plants are safe to eat.', '{"question":"A flower smells sweet. Is it safe to eat?","wrong_answer":"Yes, it smells nice","correct_answer":"Not unless an adult says it is food"}'::jsonb, 'Sweet smells and bright colours are linked with sweets and fruit.', 'Offer "Yes, it smells nice" beside "Not unless an adult says it is food" and ask the child to choose.', 'Name a pretty but poisonous plant grown near homes. Looks and smell do not tell us.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.RESOUR.PLANTS.PLANT_SAFETY.M_E3_PLT_NETTLE_HANDS', 'ENVI.G3.RESOUR.PLANTS.PLANT_SAFETY', 'Thinks stinging nettle or thorny plants can be pulled with bare hands if done quickly.', '{"question":"You need to pull out stinging nettle in the garden. What do you use?","wrong_answer":"Bare hands, quickly","correct_answer":"Gloves, a cloth or a tool"}'::jsonb, 'Speed seems to protect, as when touching something hot.', 'Offer "Bare hands, quickly" beside "Gloves, a cloth or a tool" and ask the child to choose.', 'Show gloves and a jembe. Practise pulling weeds with gloves only.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.RESOUR.PLANTS.PLANT_SAFETY.M_E3_PLT_HANDS_WASH', 'ENVI.G3.RESOUR.PLANTS.PLANT_SAFETY', 'Thinks hands do not need washing after handling plants because plants are clean.', '{"question":"You have weeded the garden. What do you do before eating?","wrong_answer":"Eat, plants are clean","correct_answer":"Wash hands with soap and water"}'::jsonb, 'Plants seem natural and clean, unlike toilets.', 'Offer "Eat, plants are clean" beside "Wash hands with soap and water" and ask the child to choose.', 'Show the soil and sap left on hands. Some plants can irritate eyes and mouths.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.RESOUR.PLANTS.EDIBLE.M_E3_EDI_ANIMAL_FOOD', 'ENVI.G3.RESOUR.PLANTS.EDIBLE', 'Thinks that a plant animals eat (grass) is edible for people.', '{"question":"Cows eat grass. Is grass edible for people?","wrong_answer":"Yes, cows eat it","correct_answer":"No, grass is not food for people"}'::jsonb, 'The child reasons that food for one is food for all.', 'Offer "Yes, cows eat it" beside "No, grass is not food for people" and ask the child to choose.', 'Show cow food and people food. People cannot digest grass. Sort pictures.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.RESOUR.PLANTS.EDIBLE.M_E3_EDI_GREEN_ALL', 'ENVI.G3.RESOUR.PLANTS.EDIBLE', 'Thinks every green leafy plant is a vegetable we can eat.', '{"question":"Is every green leafy plant a vegetable?","wrong_answer":"Yes, green leaves are vegetables","correct_answer":"No, only some, like sukuma and spinach"}'::jsonb, 'Vegetables at home are mostly green leaves.', 'Offer "Yes, green leaves are vegetables" beside "No, only some, like sukuma and spinach" and ask the child to choose.', 'Put sukuma, spinach and a weed side by side. Only some leaves are food.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.RESOUR.PLANTS.EDIBLE.M_E3_EDI_WHOLE_PLANT', 'ENVI.G3.RESOUR.PLANTS.EDIBLE', 'Thinks if a plant is edible, all its parts can be eaten.', '{"question":"We eat cassava roots. Can we eat cassava leaves raw and the stem?","wrong_answer":"Yes, every part is food","correct_answer":"No, we eat the roots (cooked); the stem is not food"}'::jsonb, 'The child calls the whole plant "food".', 'Offer "Yes, every part is food" beside "No, we eat the roots (cooked); the stem is not food" and ask the child to choose.', 'Draw a maize plant: we eat the grains, not the stalk. A mango: the fruit, not the seed or bark.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.RESOUR.PLANTS.EDIBLE.M_E3_EDI_FLOWER_FOOD', 'ENVI.G3.RESOUR.PLANTS.EDIBLE', 'Thinks flowers are edible because some plants we eat have flowers.', '{"question":"Is a rose flower food?","wrong_answer":"Yes, flowers are part of plants we eat","correct_answer":"No, roses are grown for beauty, not food"}'::jsonb, 'The child mixes "plant" with "food plant".', 'Offer "Yes, flowers are part of plants we eat" beside "No, roses are grown for beauty, not food" and ask the child to choose.', 'Sort a basket: food plants and plants for beauty or timber.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.RESOUR.ANIMALS.DOMESTIC_ANIMALS.M_E3_ANI_FOOD_ONLY', 'ENVI.G3.RESOUR.ANIMALS.DOMESTIC_ANIMALS', 'Thinks domestic animals are kept only for food.', '{"question":"Why do some families keep a donkey?","wrong_answer":"To eat it","correct_answer":"To carry water and loads"}'::jsonb, 'Animals at home are often talked about as milk, eggs and meat.', 'Offer "To eat it" beside "To carry water and loads" and ask the child to choose.', 'Make a chart of animals and their uses: donkey carries, dog guards, cat catches rats, ox ploughs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.RESOUR.ANIMALS.DOMESTIC_ANIMALS.M_E3_ANI_BEAT_WORK', 'ENVI.G3.RESOUR.ANIMALS.DOMESTIC_ANIMALS', 'Thinks beating a donkey or ox makes it work better and is part of caring.', '{"question":"A donkey stops because its load is too heavy. What should be done?","wrong_answer":"Beat it so it moves","correct_answer":"Remove some of the load and let it rest"}'::jsonb, 'Children see animals beaten on roads and copy what adults do.', 'Offer "Beat it so it moves" beside "Remove some of the load and let it rest" and ask the child to choose.', 'Discuss how the animal feels. Fair treatment: right load, rest, water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.RESOUR.ANIMALS.DOMESTIC_ANIMALS.M_E3_ANI_WATER_RAIN', 'ENVI.G3.RESOUR.ANIMALS.DOMESTIC_ANIMALS', 'Thinks animals get enough water from rain and wet grass, so they need not be watered.', '{"question":"Does a cow need to be given water every day?","wrong_answer":"No, it drinks rain","correct_answer":"Yes, every day"}'::jsonb, 'Animals graze outside, so their needs seem met by nature.', 'Offer "No, it drinks rain" beside "Yes, every day" and ask the child to choose.', 'Compare with people: we drink every day. Show a water trough.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.RESOUR.ANIMALS.DOMESTIC_ANIMALS.M_E3_ANI_SICK_WAIT', 'ENVI.G3.RESOUR.ANIMALS.DOMESTIC_ANIMALS', 'Thinks a sick animal will get better by itself and does not need a vet.', '{"question":"A goat stops eating and looks weak. What should the family do?","wrong_answer":"Wait, it will get better","correct_answer":"Call a vet or animal health worker"}'::jsonb, 'Small illnesses in people get better with rest, so the child expects the same.', 'Offer "Wait, it will get better" beside "Call a vet or animal health worker" and ask the child to choose.', 'Name the vet as the doctor for animals. A sick animal can die or spread disease.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.RESOUR.WASTE_MATERIALS.WASTE_INCOME.M_E3_WST_ALL_RUBBISH', 'ENVI.G3.RESOUR.WASTE_MATERIALS.WASTE_INCOME', 'Thinks all waste is useless rubbish that can only be burnt or thrown away.', '{"question":"Can an empty plastic bottle earn money?","wrong_answer":"No, it is rubbish","correct_answer":"Yes, it can be sold to a recycler or made into something"}'::jsonb, 'At home waste goes straight into the pit or fire.', 'Offer "No, it is rubbish" beside "Yes, it can be sold to a recycler or made into something" and ask the child to choose.', 'Show items made from waste (a bottle-top toy, a tyre sandal) and a collector buying plastics.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.RESOUR.WASTE_MATERIALS.WASTE_INCOME.M_E3_WST_PICK_ANY', 'ENVI.G3.RESOUR.WASTE_MATERIALS.WASTE_INCOME', 'Thinks children can pick any waste to sell, including broken glass and syringes.', '{"question":"You see a used syringe on the dumping site. What do you do?","wrong_answer":"Pick it and sell it","correct_answer":"Do not touch it; tell an adult"}'::jsonb, 'If waste is worth money, all of it seems worth collecting.', 'Offer "Pick it and sell it" beside "Do not touch it; tell an adult" and ask the child to choose.', 'Show a "never touch" list: broken glass, syringes, sharp tins, medical waste. Tell an adult.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.RESOUR.WASTE_MATERIALS.WASTE_INCOME.M_E3_WST_BURN_BEST', 'ENVI.G3.RESOUR.WASTE_MATERIALS.WASTE_INCOME', 'Thinks burning plastic is the best way to manage waste because it disappears.', '{"question":"What is a better way to deal with plastic bottles than burning them?","wrong_answer":"Burning, it makes them disappear","correct_answer":"Collect and sell them to a recycler, or reuse them"}'::jsonb, 'Burning removes waste from sight quickly.', 'Offer "Burning, it makes them disappear" beside "Collect and sell them to a recycler, or reuse them" and ask the child to choose.', 'Show the black smoke from burning plastic in a picture. Say it harms the lungs and air.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G3.RESOUR.WASTE_MATERIALS.WASTE_INCOME.M_E3_WST_KITCHEN_NONE', 'ENVI.G3.RESOUR.WASTE_MATERIALS.WASTE_INCOME', 'Thinks kitchen peels have no use and cannot earn anything.', '{"question":"What can banana and potato peels be used for?","wrong_answer":"Nothing","correct_answer":"To make compost manure for the garden or to sell"}'::jsonb, 'Peels smell and rot, so they seem worthless.', 'Offer "Nothing" beside "To make compost manure for the garden or to sell" and ask the child to choose.', 'Start a small compost heap at school. Show the manure after some weeks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
